{"solution_py":""""Write a deterministic manifest for regular files below a root."""
from __future__ import annotations

import hashlib
import json
import os
import stat
from pathlib import Path


def build_manifest(root: Path, output: Path) -> list[dict[str, object]]:
    root_path = root.resolve()
    output_path = output.resolve()
    rows: list[dict[str, object]] = []

    for directory, dirnames, filenames in os.walk(root_path, followlinks=False):
        dirnames[:] = sorted(name for name in dirnames if name != ".git")
        for name in sorted(filenames):
            if name.endswith(".tmp"):
                continue
            path = Path(directory) / name
            if path.resolve() == output_path:
                continue
            try:
                info = path.stat(follow_symlinks=False)
            except OSError:
                continue
            if not stat.S_ISREG(info.st_mode):
                continue

            digest = hashlib.sha256()
            with path.open("rb") as handle:
                for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                    digest.update(chunk)
            relative = path.relative_to(root_path).as_posix()
            rows.append(
                {
                    "path": relative,
                    "size": info.st_size,
                    "sha256": digest.hexdigest(),
                }
            )

    rows.sort(key=lambda row: str(row["path"]))
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(
        json.dumps(rows, ensure_ascii=True, sort_keys=True, separators=(",", ":")) + "\n",
        encoding="utf-8",
    )
    return rows
